export function importFacts(input){
 const f=structuredClone(input),p=f.participant,c=f.court,a=f.arrest;
 if(f.schemaVersion!==1||f.familyId!==FAMILY)throw Error('WRONG_FAMILY_OR_SCHEMA');
 if(!p||!c||!a)throw Error('PARTICIPANT_COURT_ARREST_REQUIRED');
 for(const k of ['firstName','lastName','dateOfBirth','sex','race','ssn','driversLicense','address','city','state','zip','phone','email'])required(p,k);
 if(!['M','F'].includes(p.sex)||!/^\d{3}-?\d{2}-?\d{4}$/.test(p.ssn))throw Error('SOURCE_IDENTITY_CONTROL_INVALID');
 for(const k of ['circuit','county'])required(c,k);
 for(const k of ['date','address','description','countyMunicipality','agency','citationNumber','county'])required(a,k);
 date(p.dateOfBirth);date(a.date);if(p.dateOfBirth>=a.date)throw Error('DATE_ORDER');
 if(countyKey(a.county)!==countyKey(c.county))throw Error('FILING_COUNTY_MISMATCH');
 if(!['false-information','qualifying-traffic'].includes(f.basis))throw Error('SOURCE_BRANCH_REQUIRED');
 const req=f.basis==='false-information'?['falseInformation','noProbableCauseNow','noChargesWillBePursued','noRelatedSIS','noCivilAction','fingerprintCardWillBeProvided']:['qualifyingChapter303OrMovingViolation','notIntoxicationRelated','allRelatedOffensesDisposed','notCDLHolder','notCommercialVehicle','noCivilAction','fingerprintCardWillBeProvided'];
 for(const key of req)if(f.attestations?.[key]!==true)throw Error(`PARTICIPANT_ATTESTATION_REQUIRED:${key}`);
 if(typeof f.criminalCaseFiled!=='boolean'||typeof f.proposedOrderRequested!=='boolean'||typeof f.feeWaiverRequested!=='boolean')throw Error('EXPLICIT_COMPONENT_CHOICES_REQUIRED');
 if(f.criminalCaseFiled){for(const k of ['caseNumber','division','level','dispositionDate'])required(f.criminalCase,k);date(f.criminalCase.dispositionDate);if(!['circuit','associate','municipal'].includes(f.criminalCase.level))throw Error('SOURCE_COURT_LEVEL');if(f.criminalCase.dispositionDate<a.date)throw Error('DISPOSITION_DATE_ORDER');}else if(f.basis==='qualifying-traffic'&&!f.attestations.allRelatedOffensesDisposed)throw Error('DISPOSITION_REQUIRED');
 if(!Array.isArray(f.respondents)||!f.respondents.length)throw Error('RESPONDENTS_REQUIRED');
 const seen=new Set();for(const r of f.respondents){if(!AGENCIES[r.kind])throw Error('UNMAPPED_AGENCY');if(seen.has(r.kind))throw Error('REPEATED_AGENCY_KIND_REQUIRES_SEPARATE_MAPPING');seen.add(r.kind);for(const k of ['organization','address','city','state','zip'])required(r,k);if(r.kind!=='repository')required(r,'label');}
 if(f.feeWaiverRequested){const q=f.feeWaiver;if(!q)throw Error('FINANCIAL_INPUTS_REQUIRED');for(const k of ['maritalStatus','dependents','residencePaymentType'])required(q,k);if(q.maritalStatus==='Married')required(q,'spouseName');if(!['mortgage','rent'].includes(q.residencePaymentType))throw Error('PAYMENT_TYPE');for(const k of ['grossSalary','publicAssistance','retirementPension','socialSecurity','childSupportIncome','maintenanceIncome','otherIncome','mortgageRent','utilities','food','debtsCardsPayment','childSupportExpense','maintenanceExpense','medicalExpense','otherExpense','cash','checking','savings','homeValue','otherRealEstate','homeLoan','automobileLoans','creditCards'])validateMoney(q[k],k);for(const [k,max] of [['automobiles',2],['personalPropertyItems',3],['otherDebtsItems',3]]){if(!Array.isArray(q[k])||q[k].length>max)throw Error('FINANCIAL_ROWS');for(const r of q[k]){required(r,'description');validateMoney(r.value,k);}}}
 const forbidden=/^(judgeSignature|judgmentDate|courtFinding|orderGranted|fileStamp|hearingDate|serviceCompleted|participantSignature|signedDate|notary|courtORI|newCaseNumber)$/i;
 const inspect=v=>{if(v&&typeof v==='object')for(const [k,x]of Object.entries(v)){if(forbidden.test(k)&&t(x))throw Error(`PROTECTED_EXECUTION_INPUT:${k}`);inspect(x)}};inspect(f);return f;
}
